PRAGMA user_version = 1;
CREATE TABLE IF NOT EXISTS users(user_key TEXT PRIMARY KEY, created_at TEXT NOT NULL, onboarding_done INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS sessions(session_id TEXT PRIMARY KEY, user_key TEXT NOT NULL REFERENCES users(user_key), started_at TEXT NOT NULL, ended_at TEXT, end_reason TEXT, lifecycle TEXT NOT NULL DEFAULT 'active', final_turn_id INTEGER, summary TEXT, state TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS turns(id INTEGER PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(session_id), user_key TEXT NOT NULL, input_id TEXT, parent_turn_id INTEGER, role TEXT NOT NULL, input_kind TEXT NOT NULL DEFAULT 'user', text TEXT NOT NULL, signals TEXT NOT NULL DEFAULT '{}', stage TEXT, mode TEXT, card TEXT, snapshot_version INTEGER, generation INTEGER, risk_level TEXT DEFAULT 'none', latency TEXT NOT NULL DEFAULT '{}', violations TEXT NOT NULL DEFAULT '[]', output_status TEXT, interrupted INTEGER DEFAULT 0, created_at TEXT NOT NULL, UNIQUE(session_id,input_id));
CREATE INDEX IF NOT EXISTS turns_session ON turns(session_id,id);
CREATE TABLE IF NOT EXISTS outputs(output_id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(session_id), turn_id INTEGER NOT NULL REFERENCES turns(id), generation INTEGER NOT NULL, data TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'submitted', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS profile(user_key TEXT NOT NULL REFERENCES users(user_key), field TEXT NOT NULL, value TEXT NOT NULL, source_turn_id INTEGER NOT NULL, source_turn_ids TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY(user_key,field));
CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY, user_key TEXT NOT NULL REFERENCES users(user_key), summary TEXT NOT NULL, pressure_type TEXT NOT NULL, event_date TEXT, importance INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'active', source_turn_ids TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(user_key,summary,source_turn_ids));
CREATE TABLE IF NOT EXISTS followups(id INTEGER PRIMARY KEY, user_key TEXT NOT NULL REFERENCES users(user_key), kind TEXT NOT NULL, content TEXT NOT NULL, due_date TEXT NOT NULL, importance INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'pending', reservation_session_id TEXT, asked_at TEXT, result TEXT, source_turn_ids TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(user_key,content,due_date));
CREATE INDEX IF NOT EXISTS followups_due ON followups(user_key,status,due_date);
CREATE TABLE IF NOT EXISTS snapshots(session_id TEXT NOT NULL REFERENCES sessions(session_id), version INTEGER NOT NULL, user_key TEXT NOT NULL, source_turn_id INTEGER NOT NULL, data TEXT NOT NULL, trigger TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(session_id,version));
CREATE TABLE IF NOT EXISTS card_usage(id INTEGER PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(session_id), action_id TEXT NOT NULL, card_id TEXT NOT NULL, outcome TEXT NOT NULL, turn_id INTEGER NOT NULL, created_at TEXT NOT NULL, UNIQUE(action_id,outcome));
CREATE TABLE IF NOT EXISTS risk_events(id INTEGER PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(session_id), turn_id INTEGER NOT NULL REFERENCES turns(id), level TEXT NOT NULL, source TEXT NOT NULL, category TEXT NOT NULL, reason TEXT NOT NULL, detection_status TEXT NOT NULL, timings TEXT NOT NULL DEFAULT '{}', handled INTEGER NOT NULL DEFAULT 0, handled_at TEXT, notification_status TEXT, created_at TEXT NOT NULL, UNIQUE(session_id,turn_id));
CREATE TABLE IF NOT EXISTS reasoner_runs(id INTEGER PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(session_id), user_key TEXT NOT NULL, kind TEXT NOT NULL, triggers TEXT NOT NULL, source_turn_id INTEGER NOT NULL, base_snapshot_version INTEGER NOT NULL, started_at TEXT NOT NULL, duration_ms REAL, status TEXT NOT NULL, result TEXT, rejected TEXT NOT NULL DEFAULT '[]', published_version INTEGER, error TEXT);
CREATE TABLE IF NOT EXISTS end_tasks(session_id TEXT PRIMARY KEY REFERENCES sessions(session_id), final_turn_id INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'pending', attempt_count INTEGER NOT NULL DEFAULT 0, last_error TEXT, updated_at TEXT NOT NULL);
